"""Tests for subject.build_topic_router_from_contract."""

from subject import build_topic_router_from_contract


def test_maps_event_type_to_model_prefixed_class_name():
    contract = {
        "published_events": [
            {
                "event_type": "NodeRegistrationAccepted",
                "topic": "onex.evt.platform.node-registration-accepted.v1",
            }
        ]
    }
    assert build_topic_router_from_contract(contract) == {
        "ModelNodeRegistrationAccepted": "onex.evt.platform.node-registration-accepted.v1"
    }


def test_multiple_events_all_mapped():
    contract = {
        "published_events": [
            {"event_type": "NodeRegistrationAccepted", "topic": "topic-a.v1"},
            {"event_type": "NodeDeregistered", "topic": "topic-b.v1"},
        ]
    }
    assert build_topic_router_from_contract(contract) == {
        "ModelNodeRegistrationAccepted": "topic-a.v1",
        "ModelNodeDeregistered": "topic-b.v1",
    }


def test_missing_published_events_key_returns_empty():
    assert build_topic_router_from_contract({}) == {}


def test_empty_published_events_returns_empty():
    assert build_topic_router_from_contract({"published_events": []}) == {}


def test_non_dict_contract_returns_empty():
    assert build_topic_router_from_contract(None) == {}
    assert build_topic_router_from_contract(["published_events"]) == {}
    assert build_topic_router_from_contract("published_events") == {}


def test_published_events_not_a_list_returns_empty():
    assert build_topic_router_from_contract({"published_events": "nope"}) == {}
    assert build_topic_router_from_contract(
        {"published_events": {"event_type": "X", "topic": "t.v1"}}
    ) == {}


def test_entry_missing_event_type_skipped():
    contract = {"published_events": [{"topic": "topic-a.v1"}]}
    assert build_topic_router_from_contract(contract) == {}


def test_entry_missing_topic_skipped():
    contract = {"published_events": [{"event_type": "NodeRegistrationAccepted"}]}
    assert build_topic_router_from_contract(contract) == {}


def test_non_dict_entries_skipped():
    contract = {
        "published_events": [
            "not-a-dict",
            42,
            None,
            {"event_type": "Real", "topic": "real.v1"},
        ]
    }
    assert build_topic_router_from_contract(contract) == {"ModelReal": "real.v1"}


def test_non_string_event_type_or_topic_skipped():
    contract = {
        "published_events": [
            {"event_type": 123, "topic": "t.v1"},
            {"event_type": "Good", "topic": 456},
            {"event_type": None, "topic": "t.v2"},
            {"event_type": "AlsoGood", "topic": None},
            {"event_type": ["A"], "topic": "t.v3"},
        ]
    }
    assert build_topic_router_from_contract(contract) == {}


def test_empty_string_event_type_or_topic_skipped():
    contract = {
        "published_events": [
            {"event_type": "", "topic": "t.v1"},
            {"event_type": "Good", "topic": ""},
        ]
    }
    assert build_topic_router_from_contract(contract) == {}


def test_valid_and_invalid_entries_mixed():
    contract = {
        "published_events": [
            {"event_type": "Keep", "topic": "keep.v1"},
            {"event_type": "", "topic": "bad.v1"},
            {"topic": "bad.v2"},
            "garbage",
            {"event_type": "Keep2", "topic": "keep2.v1"},
        ]
    }
    assert build_topic_router_from_contract(contract) == {
        "ModelKeep": "keep.v1",
        "ModelKeep2": "keep2.v1",
    }


def test_extra_entry_keys_ignored():
    contract = {
        "published_events": [
            {
                "event_type": "NodeRegistrationAccepted",
                "topic": "t.v1",
                "schema": "node_registration.accepted",
                "version": 2,
            }
        ]
    }
    assert build_topic_router_from_contract(contract) == {
        "ModelNodeRegistrationAccepted": "t.v1"
    }


def test_extra_top_level_keys_ignored():
    contract = {
        "service": "platform",
        "consumed_events": [{"event_type": "Ignore", "topic": "ignored.v1"}],
        "published_events": [{"event_type": "Keep", "topic": "keep.v1"}],
    }
    assert build_topic_router_from_contract(contract) == {"ModelKeep": "keep.v1"}
